// Merge Gujarati into translations
// Write all files
const allLangs = { gu: translations.gu, ...langData };

const namespaces = ['common','nav','dashboard','auth','purchases','sales','inventory','ledger','payments','parties','reports','profile','subscription','notifications','help','business','referrals'];

for (const [lang, nsData] of Object.entries(allLangs)) {
  const dir = join(BASE, lang);
  mkdirSync(dir, { recursive: true });
  for (const ns of namespaces) {
    const data = nsData[ns] || {};
    writeFileSync(join(dir, `${ns}.json`), JSON.stringify(data, null, 2) + '\n');
  }
  console.log(`✅ Generated ${lang}`);
}
console.log('Done!');
